sys_script.script:
(function executeRule(current, previous) {

    var verifyUrl = current.getValue('qr_verification_url');

    if (gs.nil(verifyUrl)) {
        return;
    }

    // Only generate when booking is confirmed
    if (current.getValue('booking_status') != 'confirmed') {
        return;
    }

    var qrEndpoint =
        'https://api.qrserver.com/v1/create-qr-code/' +
        '?size=250x250&data=' +
        encodeURIComponent(verifyUrl);

    var request = new sn_ws.RESTMessageV2();
    request.setHttpMethod('GET');
    request.setEndpoint(qrEndpoint);

    // Save QR response as PNG attachment
    request.saveResponseBodyAsAttachment(
        current.getTableName(),
        current.getUniqueValue(),
        'parking_qr_' + current.getValue('booking_number') + '.png'
    );

    var response = request.execute();

    if (response.getStatusCode() != 200) {
        gs.error(
            'QR generation failed. HTTP Status: ' +
            response.getStatusCode()
        );
    }

})(current, previous);
